---
// Generated from designme.dev by scripts/sync.mjs. Edit the site, then sync.
// Run cost: Live credit and token spend, with a cap that pauses the run.
// The markup, CSS and script are designme.dev's own, run by the shared core in ../core, which mounts the component when it scrolls
// into view and plays its demo. To show your own data, change run-cost.js. The markup is kept exactly as it is (is:raw).
import type { HTMLAttributes } from 'astro/types';
import '../core/designme.css';
import './run-cost.css';

export interface Props extends HTMLAttributes<'div'> {
  /** "soft" or "clean" draws it in that style. Leave it out for Blueprint, or for the style set on <html> (data-style="soft" or "clean") */
  'data-style'?: 'soft' | 'clean';
}
const { class: className, ...rest } = Astro.props;
---
<div class:list={['card', className]} data-c="run-cost" {...rest}>
  <div class="stage-in"><Fragment is:raw>
<div class="rc panel">
  <div class="rc-h"><span class="muted">Credits used</span><span class="rc-st tag"><span class="dot"></span><span class="rc-stt">Idle</span></span></div>
  <div class="rc-big"><span class="rc-n num">0</span><span class="muted"> / 2,000</span></div>
  <div class="rc-track"><div class="rc-fill"></div><div class="rc-cap" data-tip="The agent pauses here"></div></div>
  <div class="rc-rows">
    <div><span>Input tokens</span><span class="num rc-in">0</span></div>
    <div><span>Output tokens</span><span class="num rc-out">0</span></div>
    <div><span>Tool calls</span><span class="num rc-tools">0</span></div>
  </div>
  <div class="rc-f">
    <label class="rc-cap-t"><button class="toggle" role="switch" aria-checked="true" aria-label="Pause at 90 percent"></button><span>Pause at 90%</span></label>
    <button class="pill primary sm rc-go">Start run</button>
  </div>
</div>
  </Fragment></div>
</div>
<script>
  import './run-cost.js';
</script>

/* Generated from designme.dev by scripts/sync.mjs. Edit the site, then sync. */
/* ---------- Run cost ---------- */
/* the card's content sits 16px in from every edge (owner, 18 Nov); nothing in it grows or shrinks when it is pressed */
.rc{padding:var(--dm-s-4)}
.rc :is(.pill,.ib):active{transform:none}
.rc-h{display:flex;align-items:center;justify-content:space-between;font-size:12.5px}
.rc-st{transition:background .3s,color .3s}
/* the status dot is a mark: paused at the cap it takes the bright orange of the bar, while the words keep the darker text orange */
.rc-st.warn .dot{background:var(--dm-warn-mark)}
.rc-big{margin-top:6px;font-size:13px}
.rc-n{font-size:14px;font-weight:500;letter-spacing:-.8px}
/* the track is the neutral rail; the fill is the accent's mark colour, and the warning mark at the cap */
.rc-track{position:relative;height:6px;border-radius:var(--dm-r-xs);background:var(--dm-rail);margin:14px 0 var(--dm-s-4)}
.rc-fill{height:100%;width:0;border-radius:var(--dm-r-xs);background:var(--dm-accent-mark,var(--dm-accent));transition:background .4s}
.rc-cap{position:absolute;left:90%;top:-5px;bottom:-5px;width:2px;border-radius:1px;background:var(--dm-fg2);transition:opacity .3s}
.rc-cap::before{content:"";position:absolute;inset:-6px -8px}
.rc-rows{display:flex;flex-direction:column;gap:2px}
.rc-rows div{display:flex;justify-content:space-between;padding:5px 0;font-size:13px;line-height:18px;color:var(--dm-fg2)}
.rc-rows .num{color:var(--dm-fg)}
.rc-f{display:flex;align-items:center;justify-content:space-between;gap:10px;margin-top:var(--dm-s-3);padding-top:var(--dm-s-3);border-top:1px solid color-mix(in srgb,var(--dm-line) 50%,transparent)}
.rc-cap-t{display:flex;align-items:center;gap:9px;font-size:13px;color:var(--dm-fg2);cursor:pointer}
.rc-go{overflow:hidden;justify-content:flex-start}
/* Clean (owner, 17 and 18 Nov): a round card with its hairline, its content 16px in from every edge; the status chip in its
   status colours; a 6px grey rail with the accent fill (the warning mark at the cap) and an ink budget line. The rows are
   plain text (nothing to press, so no hover fill). The foot strip holds the controls 16px from the card's edges and its hairline (owner, 23 Nov): the cap's
   switch is a quiet control whose switch sits on the content's 16px edge, its hover round it, and the button a 28px pill,
   concentric with the card's corner */
:root[data-style="clean"] .rc,:root [data-style="clean"] .rc,:root [data-style="clean"].rc{padding:16px 16px 0}
:root[data-style="clean"] .rc-h,:root [data-style="clean"] .rc-h,:root [data-style="clean"].rc-h{font-size:12.5px}
:root[data-style="clean"] .rc-big .muted,:root [data-style="clean"] .rc-big .muted,:root [data-style="clean"].rc-big .muted{font-size:13px}
:root[data-style="clean"] .rc-track,:root [data-style="clean"] .rc-track,:root [data-style="clean"].rc-track{height:6px;border-radius:var(--dm-r-tiny,3px);background:var(--dm-rail);margin:12px 0 10px}
:root[data-style="clean"] .rc-fill,:root [data-style="clean"] .rc-fill,:root [data-style="clean"].rc-fill{border-radius:var(--dm-r-tiny,3px)}
:root[data-style="clean"] .rc-cap,:root [data-style="clean"] .rc-cap,:root [data-style="clean"].rc-cap{background:var(--dm-fg)}
:root[data-style="clean"] .rc-f,:root [data-style="clean"] .rc-f,:root [data-style="clean"].rc-f{margin:11px -16px 0;padding:var(--dm-strip-y) 16px;border-top:1px solid var(--dm-line);background:var(--dm-strip);border-radius:0 0 var(--dm-r-card) var(--dm-r-card)}
:root[data-style="clean"] .rc-cap-t,:root [data-style="clean"] .rc-cap-t,:root [data-style="clean"].rc-cap-t{height:28px;padding:0 10px 0 8px;border-radius:var(--dm-r-pill);gap:8px;transition:background-color var(--dm-t-fast) var(--dm-ease),color var(--dm-t-fast) var(--dm-ease)}
@media (hover:hover) and (pointer:fine){:root[data-style="clean"] .rc-cap-t:hover,:root [data-style="clean"] .rc-cap-t:hover,:root [data-style="clean"].rc-cap-t:hover{background:var(--dm-hover);color:var(--dm-fg)}}
/* (owner, 22 Nov: "foot buttons aligned") the switch itself sits on the content's 16px column, where Credits used starts, its
   hover pill reaching 8px out round it */
:root[data-style="clean"] .rc-cap-t,:root [data-style="clean"] .rc-cap-t,:root [data-style="clean"].rc-cap-t{margin-left:-8px}
/* the running chip is the accent's tint with its words in the accent's text colour: blue in light mode, white in dark (owner,
   22 Nov: Clean dark's accents are white) */
:root[data-style="clean"] .rc-st.b,:root [data-style="clean"] .rc-st.b,:root [data-style="clean"].rc-st.b{background:var(--dm-accent-bg);color:var(--dm-accent-fg,var(--dm-accent))}
:root[data-style="clean"] .rc-go,:root [data-style="clean"] .rc-go,:root [data-style="clean"].rc-go{transition:transform var(--dm-t-fast) var(--dm-ease),box-shadow var(--dm-t-fast) var(--dm-ease),background-color var(--dm-t-fast) var(--dm-ease),color var(--dm-t-fast) var(--dm-ease)}
@media (prefers-reduced-motion:reduce){:root[data-style="clean"] .rc-cap-t,:root [data-style="clean"] .rc-cap-t,:root [data-style="clean"].rc-cap-t{transition:none}}

// Generated from designme.dev by scripts/sync.mjs. Edit the site, then sync.
import { $, DM, REDUCE, swap } from '../core/core.js';
DM.def('run-cost', (r, c) => {
  // the label crossfades on its own span, so the button itself never blurs
  const go = $('.rc-go', r); go.innerHTML = '<span class="rc-gl">Start run</span>'; const gl = () => $('.rc-gl', go);
  // the button is as wide as its words and eases to its new width when they change, keeping no room for a longer one (owner, 18 Nov)
  const easeW = el => { let w = 0, busy = null; const ro = new ResizeObserver(() => { if (busy) return; const w1 = el.getBoundingClientRect().width;
    if (!REDUCE && w && Math.abs(w1 - w) > .5){ busy = el.animate([{ width:w + 'px' }, { width:w1 + 'px' }], { duration:340, easing:'cubic-bezier(.23,1,.32,1)' }); busy.finished.catch(() => {}).then(() => { busy = null; w = el.getBoundingClientRect().width; }); } w = w1; });
    ro.observe(el); c.offs.push(() => ro.disconnect()); };
  easeW(go);
  const tg = $('.toggle', r), cap = $('.rc-cap', r), fill = $('.rc-fill', r), st = $('.rc-st', r), stt = $('.rc-stt', r);
  let used = 0, inT = 0, outT = 0, tools = 0, running = false, limit = 1800, loop = 0;
  const fmt = n => Math.round(n).toLocaleString('en-US');
  const paint = () => { $('.rc-n', r).textContent = fmt(used); fill.style.width = (used / 2000 * 100) + '%'; $('.rc-in', r).textContent = fmt(inT); $('.rc-out', r).textContent = fmt(outT); $('.rc-tools', r).textContent = tools; };
  const status = (t, cls) => { st.className = 'rc-st tag ' + (cls || ''); swap(stt, t); };
  const capOn = () => tg.getAttribute('aria-checked') === 'true';
  $('.rc-cap-t', r).onclick = e => { e.preventDefault(); tg.setAttribute('aria-checked', !capOn()); cap.style.opacity = capOn() ? 1 : .2; limit = capOn() ? 1800 : 2000; if (!running && used < limit && used > 0) go.disabled = false; };
  function stop(t, cls){ running = false; clearInterval(loop); status(t, cls); }
  go.onclick = () => {
    if (running){ stop('Stopped'); swap(gl(), 'Resume'); return; }
    if (used >= 2000){ used = inT = outT = tools = 0; paint(); }
    running = true; status('Running', 'b'); swap(gl(), 'Stop'); go.className = 'pill soft sm rc-go'; fill.style.background = 'var(--dm-accent-mark,var(--dm-accent))';
    loop = c.every(90, () => {
      used = Math.min(2000, used + 8 + Math.random() * 18); inT += 120 + Math.random() * 220; outT += 30 + Math.random() * 70; if (Math.random() < .12) tools++;
      paint();
      if (used >= limit){
        used = limit; paint();
        if (limit < 2000){ stop('Paused at 90%', 'warn'); fill.style.background = 'var(--dm-warn-mark)'; swap(gl(), 'Raise cap'); go.className = 'pill primary sm rc-go'; go.onclick2 = true; }
        else { stop('Budget used', 'bad'); swap(gl(), 'Start over'); go.className = 'pill primary sm rc-go'; }
      }
    });
  };
  const orig = go.onclick;
  go.addEventListener('click', e => { if (go.onclick2 && !running){ go.onclick2 = false; e.stopImmediatePropagation(); tg.setAttribute('aria-checked','false'); cap.style.opacity = .2; limit = 2000; orig(); } }, true);
  paint();
  // the run starts by itself once the card has settled, so the spend can be seen climbing to the cap
  c.auto(1500, () => { if (!running && !used) go.click(); });
});
